/* ===== iOS/mobile WebKit repaint fix =====
   OneTrust's SDK re-parents the banner buttons on every window resize at
   <=600px (setBannerBtn), inside a card the stock template makes a
   composited fixed + overflow-y:auto scroller. On iOS WebKit the re-inserted
   buttons stay unpainted until a touch forces invalidation. Pinning the card
   to its own stable compositor layer makes mutations paint immediately;
   animation:none kills the (already visually inert) GDPR slide-in churn. */
#onetrust-banner-sdk.otFloatingRoundedCorner {
  -webkit-transform: translateZ(0);
  transform: translateZ(0);
  animation: none !important;
}

@media only screen and (max-width: 600px) {
  #onetrust-banner-sdk.otFloatingRoundedCorner {
    overflow: visible !important;
    max-height: none !important;
  }
}
